def records(text):
    records = []
    for line in text.splitlines():
        if not line.strip():
            continue
        try:
            obj = json.loads(line)
        except json.JSONDecodeError as e:
            raise ValueError(f"{e.line}.{e.lineno}: not an object JSON")
        if not isinstance(obj, dict):
            raise ValueError(f"{e.line}.{e.lineno}: not an object JSON")
        records.append(obj)
    return records

